  SIGNAL client_fifo1_out4                : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL DataTypeConv1_out1               : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL DataTypeConv1_out1_signed        : vector_of_signed8(0 TO 1);  -- int8 [2]
  SIGNAL Multiport_Switch_wrData_out1     : vector_of_signed8(0 TO 1);  -- int8 [2]
  SIGNAL Multiport_Switch_wrData_out1_1   : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL DataTypeConv8_out1               : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL HDL_FWFT_FIFO10_out1             : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL HDL_FWFT_FIFO10_out2deadOutdeadOut : std_logic;
  SIGNAL HDL_FWFT_FIFO10_out3deadOutdeadOut : std_logic;
  SIGNAL HDL_FWFT_FIFO10_out4             : std_logic;
  SIGNAL Logical_Operator6_out1           : std_logic;
  SIGNAL Delay9_out1                      : std_logic;
  SIGNAL send                             : std_logic;
  SIGNAL client_fifo1_out1                : std_logic;
  SIGNAL Multiport_Switch_length1_out1    : std_logic;
  SIGNAL wr_addr                          : std_logic_vector(31 DOWNTO 0);  -- ufix32
  SIGNAL wr_validdeadOutdeadOut           : std_logic;
  SIGNAL state_outdeadOutdeadOut          : std_logic_vector(3 DOWNTO 0);  -- ufix4
  SIGNAL DataTypeConv9_out1               : vector_of_std_logic_vector8(0 TO 1);  -- ufix8 [2]
  SIGNAL HDL_FIFO_out1                    : std_logic_vector(2 DOWNTO 0);  -- ufix3
  SIGNAL HDL_FIFO_out1_unsigned           : unsigned(2 DOWNTO 0);  -- ufix3
  SIGNAL Compare_To_Constant7_out1        : std_logic;
  SIGNAL wr_complete                      : std_logic;
  SIGNAL wr_complete_1                    : std_logic;
  SIGNAL Delay3_out1                      : std_logic;
  SIGNAL Logical_Operator7_out1           : std_logic;
  SIGNAL Compare_To_Constant8_out1        : std_logic;
  SIGNAL Logical_Operator8_out1           : std_logic;
  SIGNAL Compare_To_Constant9_out1        : std_logic;
  SIGNAL Logical_Operator9_out1           : std_logic;
  SIGNAL Compare_To_Constant1_out1        : std_logic;
  SIGNAL Logical_Operator1_out1           : std_logic;
  SIGNAL Compare_To_Constant2_out1        : std_logic;
  SIGNAL Logical_Operator2_out1           : std_logic;
  SIGNAL Mux_out1                         : std_logic_vector(9 DOWNTO 0);  -- boolean [10]

BEGIN
  u_DataTypeConv2 : MyProc_src_DataTypeConv2_block1
    PORT MAP( InData => wr_data_in2,  -- int8 [2]
              OutData => DataTypeConv2_out1  -- int8 [2]
              );

  u_DataTypeConv4 : MyProc_src_DataTypeConv4
    PORT MAP( InData => wr_data_in3,  -- int8 [2]
              OutData => DataTypeConv4_out1  -- int8 [2]
              );

  u_DataTypeConv6 : MyProc_src_DataTypeConv6
    PORT MAP( InData => wr_data_in4,  -- int8 [2]
              OutData => DataTypeConv6_out1  -- int8 [2]
              );

  u_DataTypeConv10 : MyProc_src_DataTypeConv10
    PORT MAP( InData => wr_data_in5,  -- int8 [2]
              OutData => DataTypeConv10_out1  -- int8 [2]
              );

  u_DataTypeConv : MyProc_src_DataTypeConv_block18
    PORT MAP( InData => wr_data_in1,  -- int8 [2]
              OutData => DataTypeConv_out1  -- int8 [2]
              );

  u_data_counter2 : MyProc_src_data_counter2
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              length => wr_len,  -- uint32
              wr_valid => wr_valid,
              done => done
              );

  u_HDL_FIFO2 : MyProc_src_HDL_FIFO2_block1
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              In_rsvd => Constant1_out1deadIn,
              Push => Multiport_Switch_valid_out1,
              Pop => wr_valid,
              Out_rsvd => HDL_FIFO2_out1deadOut,
              Empty => HDL_FIFO2_out2
              );

  u_client_fifo5 : MyProc_src_client_fifo5
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              cur_counter => req_counter_out,  -- ufix3
              send => Logical_Operator12_out1,
              doneIn => done_3,
              wr_m2s_wr_valid => axi_wr_m2s_in5_wr_valid,
              wr_m2s_wr_len => axi_wr_m2s_in5_wr_len,  -- uint32
              wr_m2s_wr_addr => axi_wr_m2s_in5_wr_addr,  -- uint32
              wr_data => DataTypeConv10_out1,  -- int8 [2]
              resetIn => reset_3,
              start => client_fifo5_out1,
              ready => Mux_out1(8),
              offset => client_fifo5_out3,  -- uint32
              data => client_fifo5_out4,  -- int8 [2]
              valid => client_fifo5_out5,
              length => client_fifo5_out6  -- uint32
              );

  u_DataTypeConv11 : MyProc_src_DataTypeConv11
    PORT MAP( InData => client_fifo5_out4,  -- int8 [2]
              OutData => DataTypeConv11_out1  -- int8 [2]
              );

  u_client_fifo4 : MyProc_src_client_fifo4
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              cur_counter => req_counter_out,  -- ufix3
              send => Logical_Operator12_out1,
              doneIn => done_4,
              wr_m2s_wr_addr => axi_wr_m2s_in4_wr_addr,  -- uint32
              wr_m2s_wr_len => axi_wr_m2s_in4_wr_len,  -- uint32
              wr_m2s_wr_valid => axi_wr_m2s_in4_wr_valid,
              wr_data => DataTypeConv6_out1,  -- int8 [2]
              resetIn => reset_4,
              start => client_fifo4_out1,
              ready => Mux_out1(6),
              offset => client_fifo4_out3,  -- uint32
              data => client_fifo4_out4,  -- int8 [2]
              valid => client_fifo4_out5,
              length => client_fifo4_out6  -- uint32
              );

  u_DataTypeConv7 : MyProc_src_DataTypeConv7
    PORT MAP( InData => client_fifo4_out4,  -- int8 [2]
              OutData => DataTypeConv7_out1  -- int8 [2]
              );

  u_client_fifo3 : MyProc_src_client_fifo3
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              cur_counter => req_counter_out,  -- ufix3
              send => Logical_Operator12_out1,
              doneIn => done_5,
              wr_m2s_wr_valid => axi_wr_m2s_in3_wr_valid,
              wr_m2s_wr_len => axi_wr_m2s_in3_wr_len,  -- uint32
              wr_m2s_wr_addr => axi_wr_m2s_in3_wr_addr,  -- uint32
              wr_data => DataTypeConv4_out1,  -- int8 [2]
              resetIn => reset_5,
              start => client_fifo3_out1,
              ready => Mux_out1(4),
              offset => client_fifo3_out3,  -- uint32
              data => client_fifo3_out4,  -- int8 [2]
              valid => client_fifo3_out5,
              length => client_fifo3_out6  -- uint32
              );

  u_DataTypeConv5 : MyProc_src_DataTypeConv5
    PORT MAP( InData => client_fifo3_out4,  -- int8 [2]
              OutData => DataTypeConv5_out1  -- int8 [2]
              );

  u_client_fifo2 : MyProc_src_client_fifo2
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              cur_counter => req_counter_out,  -- ufix3
              send => Logical_Operator12_out1,
              doneIn => done_6,
              wr_m2s_wr_addr => axi_wr_m2s_in2_wr_addr,  -- uint32
              wr_m2s_wr_len => axi_wr_m2s_in2_wr_len,  -- uint32
              wr_m2s_wr_valid => axi_wr_m2s_in2_wr_valid,
              wr_data => DataTypeConv2_out1,  -- int8 [2]
              resetIn => reset_6,
              start => client_fifo2_out1,
              ready => Mux_out1(2),
              offset => client_fifo2_out3,  -- uint32
              data => client_fifo2_out4,  -- int8 [2]
              valid => client_fifo2_out5,
              length => client_fifo2_out6  -- uint32
              );

  u_DataTypeConv3 : MyProc_src_DataTypeConv3_block2
    PORT MAP( InData => client_fifo2_out4,  -- int8 [2]
              OutData => DataTypeConv3_out1  -- int8 [2]
              );

  u_DataTypeConv1 : MyProc_src_DataTypeConv1_block14
    PORT MAP( InData => client_fifo1_out4,  -- int8 [2]
              OutData => DataTypeConv1_out1  -- int8 [2]
              );

  u_DataTypeConv8 : MyProc_src_DataTypeConv8
    PORT MAP( InData => Multiport_Switch_wrData_out1_1,  -- int8 [2]
              OutData => DataTypeConv8_out1  -- int8 [2]
              );

  u_HDL_FWFT_FIFO10 : MyProc_src_HDL_FWFT_FIFO10
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              In_rsvd => DataTypeConv8_out1,  -- int8 [2]
              Push => Multiport_Switch_valid_out1,
              Pop => wr_valid,
              Out_rsvd => HDL_FWFT_FIFO10_out1,  -- int8 [2]
              Empty => HDL_FWFT_FIFO10_out2deadOutdeadOut,
              Full => HDL_FWFT_FIFO10_out3deadOutdeadOut,
              AFull => HDL_FWFT_FIFO10_out4
              );

  u_client_fifo1 : MyProc_src_client_fifo1
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              cur_counter => req_counter_out,  -- ufix3
              send => Logical_Operator12_out1,
              doneIn => done_2,
              wr_m2s_wr_addr => axi_wr_m2s_in1_wr_addr,  -- uint32
              wr_m2s_wr_len => axi_wr_m2s_in1_wr_len,  -- uint32
              wr_m2s_wr_valid => axi_wr_m2s_in1_wr_valid,
              wr_data => DataTypeConv_out1,  -- int8 [2]
              resetIn => reset_2,
              start => client_fifo1_out1,
              ready => Mux_out1(0),
              offset => client_fifo1_out3,  -- uint32
              data => client_fifo1_out4,  -- int8 [2]
              valid => client_fifo1_out5,
              length => client_fifo1_out6  -- uint32
              );

  u_DMA_wrReq : MyProc_src_DMA_wrReq
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              start => Multiport_Switch_length1_out1,
              length => std_logic_vector(Multiport_Switch_length_out1),  -- uint32
              offset => std_logic_vector(Multiport_Switch_offset_out1),  -- uint32
              valid => Multiport_Switch_valid_out1,
              wr_complete => done,
              wr_addr => wr_addr,  -- uint32
              wr_len => wr_len,  -- uint32
              wr_valid => wr_validdeadOutdeadOut,
              req_counter_out => req_counter_out,  -- ufix3
              send => send,
              done => done_1,
              reset_1 => reset_1,
              state_out => state_outdeadOutdeadOut  -- ufix4
              );

  u_DataTypeConv9 : MyProc_src_DataTypeConv9
    PORT MAP( InData => HDL_FWFT_FIFO10_out1,  -- int8 [2]
              OutData => DataTypeConv9_out1  -- int8 [2]
              );

  u_HDL_FIFO : MyProc_src_HDL_FIFO_block19
    PORT MAP( clk => clk,
              reset => reset,
              enb => enb,
              In_rsvd => req_counter_out,  -- ufix3
              Push => done,
              Pop => axi_wr_s2m_i_wr_complete,
              Out_rsvd => HDL_FIFO_out1  -- ufix3
              );

  Constant1_out1deadIn <= '0';

  wr_ready <= axi_wr_s2m_i_wr_ready;

  client_fifo5_out3_unsigned <= unsigned(client_fifo5_out3);

  client_fifo4_out3_unsigned <= unsigned(client_fifo4_out3);

  client_fifo3_out3_unsigned <= unsigned(client_fifo3_out3);

  client_fifo2_out3_unsigned <= unsigned(client_fifo2_out3);

  client_fifo1_out3_unsigned <= unsigned(client_fifo1_out3);

  
  Multiport_Switch_offset_out1 <= client_fifo1_out3_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#0#, 3) ELSE
      client_fifo2_out3_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#1#, 3) ELSE
      client_fifo3_out3_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#2#, 3) ELSE
      client_fifo4_out3_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#3#, 3) ELSE
      client_fifo5_out3_unsigned;

  client_fifo5_out6_unsigned <= unsigned(client_fifo5_out6);

  client_fifo4_out6_unsigned <= unsigned(client_fifo4_out6);

  client_fifo3_out6_unsigned <= unsigned(client_fifo3_out6);

  client_fifo2_out6_unsigned <= unsigned(client_fifo2_out6);

  client_fifo1_out6_unsigned <= unsigned(client_fifo1_out6);

  
  Multiport_Switch_length_out1 <= client_fifo1_out6_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#0#, 3) ELSE
      client_fifo2_out6_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#1#, 3) ELSE
      client_fifo3_out6_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#2#, 3) ELSE
      client_fifo4_out6_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#3#, 3) ELSE
      client_fifo5_out6_unsigned;

  reset_2 <= reset_1;

  done_2 <= done_1;

  Logical_Operator13_out1 <=  NOT HDL_FIFO2_out2;

  wr_valid <= Logical_Operator13_out1 AND wr_ready;

  
  Multiport_Switch_valid_out1 <= client_fifo1_out5 WHEN req_counter_out_unsigned = to_unsigned(16#0#, 3) ELSE
      client_fifo2_out5 WHEN req_counter_out_unsigned = to_unsigned(16#1#, 3) ELSE
      client_fifo3_out5 WHEN req_counter_out_unsigned = to_unsigned(16#2#, 3) ELSE
      client_fifo4_out5 WHEN req_counter_out_unsigned = to_unsigned(16#3#, 3) ELSE
      client_fifo5_out5;

  reset_3 <= reset_1;

  done_3 <= done_1;

  outputgen5: FOR k IN 0 TO 1 GENERATE
    DataTypeConv11_out1_signed(k) <= signed(DataTypeConv11_out1(k));
  END GENERATE;

  reset_4 <= reset_1;

  done_4 <= done_1;

  outputgen4: FOR k IN 0 TO 1 GENERATE
    DataTypeConv7_out1_signed(k) <= signed(DataTypeConv7_out1(k));
  END GENERATE;

  reset_5 <= reset_1;

  done_5 <= done_1;

  outputgen3: FOR k IN 0 TO 1 GENERATE
    DataTypeConv5_out1_signed(k) <= signed(DataTypeConv5_out1(k));
  END GENERATE;

  reset_6 <= reset_1;

  done_6 <= done_1;

  outputgen2: FOR k IN 0 TO 1 GENERATE
    DataTypeConv3_out1_signed(k) <= signed(DataTypeConv3_out1(k));
  END GENERATE;

  outputgen1: FOR k IN 0 TO 1 GENERATE
    DataTypeConv1_out1_signed(k) <= signed(DataTypeConv1_out1(k));
  END GENERATE;

  Multiport_Switch_wrData_output : PROCESS (DataTypeConv11_out1_signed, DataTypeConv1_out1_signed,
       DataTypeConv3_out1_signed, DataTypeConv5_out1_signed,
       DataTypeConv7_out1_signed, req_counter_out_unsigned)
  BEGIN
    IF req_counter_out_unsigned = to_unsigned(16#0#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv1_out1_signed;
    ELSIF req_counter_out_unsigned = to_unsigned(16#1#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv3_out1_signed;
    ELSIF req_counter_out_unsigned = to_unsigned(16#2#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv5_out1_signed;
    ELSIF req_counter_out_unsigned = to_unsigned(16#3#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv7_out1_signed;
    ELSE 
      Multiport_Switch_wrData_out1 <= DataTypeConv11_out1_signed;
    END IF;
  END PROCESS Multiport_Switch_wrData_output;


  outputgen: FOR k IN 0 TO 1 GENERATE
    Multiport_Switch_wrData_out1_1(k) <= std_logic_vector(Multiport_Switch_wrData_out1(k));
  END GENERATE;

  Logical_Operator6_out1 <=  NOT HDL_FWFT_FIFO10_out4;

  Delay9_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay9_out1 <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        Delay9_out1 <= Logical_Operator6_out1;
      END IF;
    END IF;
  END PROCESS Delay9_process;


  Logical_Operator12_out1 <= send AND Delay9_out1;

  req_counter_out_unsigned <= unsigned(req_counter_out);

  
  Multiport_Switch_length1_out1 <= client_fifo1_out1 WHEN req_counter_out_unsigned = to_unsigned(16#0#, 3) ELSE
      client_fifo2_out1 WHEN req_counter_out_unsigned = to_unsigned(16#1#, 3) ELSE
      client_fifo3_out1 WHEN req_counter_out_unsigned = to_unsigned(16#2#, 3) ELSE
      client_fifo4_out1 WHEN req_counter_out_unsigned = to_unsigned(16#3#, 3) ELSE
      client_fifo5_out1;

  axi_wr_m2s_wr_valid <= wr_valid;

  HDL_FIFO_out1_unsigned <= unsigned(HDL_FIFO_out1);

  
  Compare_To_Constant7_out1 <= '1' WHEN HDL_FIFO_out1_unsigned = to_unsigned(16#0#, 3) ELSE
      '0';

  wr_complete <= axi_wr_s2m_i_wr_complete;

  wr_complete_1 <= wr_complete;

  Delay3_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay3_out1 <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        Delay3_out1 <= wr_complete_1;
      END IF;
    END IF;
  END PROCESS Delay3_process;


  Logical_Operator7_out1 <= Compare_To_Constant7_out1 AND Delay3_out1;

  
  Compare_To_Constant8_out1 <= '1' WHEN HDL_FIFO_out1_unsigned = to_unsigned(16#1#, 3) ELSE
      '0';

  Logical_Operator8_out1 <= Compare_To_Constant8_out1 AND Delay3_out1;

  
  Compare_To_Constant9_out1 <= '1' WHEN HDL_FIFO_out1_unsigned = to_unsigned(16#2#, 3) ELSE
      '0';

  Logical_Operator9_out1 <= Compare_To_Constant9_out1 AND Delay3_out1;

  
  Compare_To_Constant1_out1 <= '1' WHEN HDL_FIFO_out1_unsigned = to_unsigned(16#3#, 3) ELSE
      '0';

  Logical_Operator1_out1 <= Compare_To_Constant1_out1 AND Delay3_out1;

  
  Compare_To_Constant2_out1 <= '1' WHEN HDL_FIFO_out1_unsigned = to_unsigned(16#4#, 3) ELSE
      '0';

  Logical_Operator2_out1 <= Compare_To_Constant2_out1 AND Delay3_out1;

  Mux_out1(1) <= Logical_Operator7_out1;
  Mux_out1(3) <= Logical_Operator8_out1;
  Mux_out1(5) <= Logical_Operator9_out1;
  Mux_out1(7) <= Logical_Operator1_out1;
  Mux_out1(9) <= Logical_Operator2_out1;

  axi_wr_s2m_o <= Mux_out1;

  axi_wr_m2s_wr_addr <= wr_addr;

  axi_wr_m2s_wr_len <= wr_len;

  wr_data_out <= DataTypeConv9_out1;

  wr_reqCounter <= req_counter_out;

END rtl;

